import ignorePlugin from 'esbuild-plugin-ignore';
import { SourceMapConsumer, SourceMapGenerator, type Mapping } from "source-map";
import { build, BuildOptions, context as esbuild } from 'esbuild';
import { Port } from '@teambit/toolbox.network.get-port';
import { CAPSULE_ARTIFACTS_DIR } from '@teambit/builder';
import type {
  Application,
  DeployFn,
  AppContext,
  ApplicationInstance,
  BuildFn,
  AppBuildResult,
  AppBuildContext,
} from '@teambit/application';
import { createRequire } from 'node:module';
import { join, resolve, dirname } from 'node:path';
import type { Workspace } from '@teambit/workspace';
import { WorkspaceAspect } from '@teambit/workspace';
import { compact, pickBy, identity } from 'lodash-es';
import { fileURLToPath } from 'node:url';
import type { NodeServerOptions } from './node-server-options.js';
import { startPlugin } from './start-plugin.js';
import { SingleExecutableApplications } from './sea.js';
import { readFileSync } from 'node:fs';
import { readdir, unlink, writeFile } from 'node:fs/promises';
import { createHash } from 'node:crypto';
import fs from 'fs-extra';



export class NodeServer implements Application {
  constructor(
    readonly name: string,
    readonly mainFile: Promise<string> | string,
    readonly customBuild?: BuildFn,
    readonly deploy?: DeployFn,
    readonly nodeBin: string = 'node',
    readonly binary: boolean = false,
    readonly artifactName: string = 'app-bundle',
    readonly bundleFileName: string = `${name}.cjs`,
    readonly esbuildOptions: BuildOptions = {},
    readonly showNameInOutputs = true,
    readonly distDir: string = 'dist',
    readonly portRange: [number, number] = [5000, 5100]
  ) {}

  applicationType = 'node';

  private async getFileUrl() {
    const url = fileURLToPath(await this.mainFile);
    return url;
  }

  private async getMainFile(componentPath: string) {
    const entryFile = await this.mainFile;
    const mainFile = entryFile.startsWith('file:')
      ? await this.getFileUrl()
      : resolve(componentPath, entryFile);
    return mainFile;
  }

  async run(context: AppContext): Promise<ApplicationInstance> {
    const mainFile = await this.getMainFile(context.workspaceComponentPath);
    const [fromPort, toPort] = this.portRange;
    const port = context.port || (await Port.getPort(fromPort, toPort));
    const envVars = this.computeEnvVars({
      ...context.envVariables,
      PORT: port.toString(),
    });

    const root = context.hostRootDir;
    const outfile = join(root, this.distDir, this.bundleFileName);
    const packageIndex = await this.computePackageMap(context);
    const config = this.computeConfig(
      mainFile,
      outfile,
      context.workspaceComponentPath,
      {
        ...packageIndex,
        // ...rootAlias
      },
      envVars,
    );
    const esContext = await esbuild(config);
    await esContext.watch();
    
    return {
      port,
    };
  }

  private computeEnvVars(envVars: Record<string, string>) {
    const keys = Object.keys(envVars);
    return keys.reduce((acc, key) => {
      const keyName = `process.env.${key}`;
      if (acc[keyName]) return acc;
      acc[keyName] = `"${envVars[key]}"`;
      return acc;
    }, {});
  }

  private computeBuildEnvVars(envVars: Record<string, string>) {
    const keys = Object.keys(envVars);
    const vars = keys.reduce((acc: Record<string, string>, key) => {
      if (acc[key]) return acc;
      acc[key] = `${envVars[key]}`;
      return acc;
    }, {});
    return {
      ...this.computeEnvVars(envVars),
      'process.env.HARMONY_BUILD_METADATA': `${JSON.stringify(vars)}`,
    };
  }

  private async computePackageMap(
    context: AppContext
  ): Promise<Record<string, string>> {
    const workspace = context.getAspect<Workspace>(WorkspaceAspect.id);
    const components = workspace ? await workspace.list() : [];
    const packageListDist: [string, string][] = compact(
      components.map((c) => [
        `${workspace?.componentPackageName(c)}/dist`,
        workspace.componentDir(c.id),
      ])
    );
    const packageList: [string, string][] = compact(
      components.map((c) => [
        workspace?.componentPackageName(c),
        workspace.componentDir(c.id),
      ])
    );

    const allPackages = packageList.concat(packageListDist);

    const packageIndex = allPackages.reduce((acc, [packageName, dir]) => {
      if (acc[packageName]) return acc;
      acc[packageName] = dir;
      return acc;
    }, {});

    return packageIndex;
  }

  private computeConfig(
    mainFile: string,
    outFile: string,
    workDir: string,
    packageIndex: Record<string, string>,
    define?: Record<string, string>,
  ): BuildOptions {


    const pkgRegex = /\/node_modules\/(@[^/]+\/[^/]+)\/(.+)$/;

    function resolveSource(source: string) {
      const match = source.match(pkgRegex);
      if (match && match[1] && match[2] && packageIndex[match[1]]) {
        return join(packageIndex[match[1]], match[2].replaceAll('dist', ''));
      }
      return source;
    }

    let lastRawHash: string | undefined;

    const sourceMapPulgin = {
      name: 'sourceMapPulgin',
      setup(build) {
        build.onEnd(async (result) => {
          if (result.errors.length > 0) return;
          const sourceMapFile = `${outFile}.map`;
          const rawContent = readFileSync(sourceMapFile).toString();

          // Skip rewrite if source map hasn't changed
          const rawHash = createHash('sha256').update(rawContent).digest('hex').slice(0, 8);
          if (rawHash === lastRawHash) return;
          lastRawHash = rawHash;

          const rawSourceMap = JSON.parse(rawContent);
          const consumer = await new SourceMapConsumer(rawSourceMap);
          const generator = new SourceMapGenerator({
            file: rawSourceMap.file,
            sourceRoot: rawSourceMap.sourceRoot,
          });

          consumer.eachMapping((mapping) => {
              if (mapping.source != null && mapping.originalLine != null) {
                generator.addMapping({
                  generated: {
                    line: mapping.generatedLine,
                    column: mapping.generatedColumn,
                  },
                  original: {
                    line: mapping.originalLine,
                    column: mapping.originalColumn,
                  },
                  source: resolveSource(mapping.source),
                  name: mapping.name,
                });
              } else {
                generator.addMapping({
                  generated: {
                    line: mapping.generatedLine,
                    column: mapping.generatedColumn,
                  },
                } as Mapping);
              }
          });

          if (rawSourceMap.sourcesContent) {
            rawSourceMap.sources.forEach((src, i) => {
              generator.setSourceContent(resolveSource(src), rawSourceMap.sourcesContent[i]);
            });
          }

          const outDir = dirname(sourceMapFile);
          const mapContent = generator.toString()
          const hash = createHash('sha256').update(mapContent).digest('hex').slice(0, 8);
          const sourceMap = `app.${hash}.cjs.map`;
          const sourceMapPath = join(outDir, sourceMap);
          const exists = await fs.pathExists(sourceMapPath)

          const app = readFileSync(outFile, 'utf8');
          const appNewMap = app.replace('//# sourceMappingURL=node.cjs.map', `//# sourceMappingURL=${sourceMap}`);
          await writeFile(outFile, appNewMap);

          if (exists) return;
          const files = await readdir(outDir);
          const oldMaps = files.filter((f) => /^app\.[a-f0-9]{8,}\.cjs\.map$/.test(f));
          await Promise.all(oldMaps.map((f) => unlink(join(outDir, f))));

          await writeFile(join(outDir, sourceMap), mapContent);
        })
      },
    }
    

    return {
      platform: 'node',
      define,
      entryPoints: [mainFile],
      bundle: true,
      loader: { '.png': 'binary', '.node': 'binary' },
      outfile: outFile,
      keepNames: true,
      sourcemap: true,
      // sourcesContent: false,
      // alias: packageIndex,
      plugins: [startPlugin(outFile), sourceMapPulgin],
      ...this.esbuildOptions,
    };
  }

  get outputDir() {
    return join(CAPSULE_ARTIFACTS_DIR, this.artifactName);
  }

  async build(context: AppBuildContext): Promise<AppBuildResult> {
    if (this.customBuild) return this.customBuild(context);
    const vars = pickBy(
      {
        ...context.envVariables,
        APP_NAME: context.appName,
        APP_VERSION: context.appComponent?.id?.version,
        LANE_ID: context?.laneId?.toString(),
      },
      identity
    );

    const envVars = this.computeBuildEnvVars(vars);
    const rootDir = context.capsule.path;
    const outputDir = join(rootDir, this.outputDir);
    const mainFile = await this.getMainFile(context.capsule.path);
    const outFile = join(outputDir, this.bundleFileName);
    const result = await build({
      define: envVars,
      ...this.esbuildOptions,
      loader: { '.png': 'binary', '.node': 'binary' },
      entryPoints: [mainFile],
      plugins: [
        ignorePlugin([
          // TODO: gilad and zoltan need to fix it, not working with fuse? or esbuild issue?
          { resourceRegExp: new RegExp('^../build/Release/cpufeatures.node') },
        ]),
      ],
      bundle: true,
      platform: 'node',
      outfile: outFile,
    });

    if (!this.binary) {
      // await prependFile(outFile, '#!/usr/bin/env node \n');
      // execSync(`chmod +x ${outFile}`);
    }

    if (this.binary) {
      const sea = new SingleExecutableApplications({
        outPutRootDir: outputDir,
        outPutFileName: this.bundleFileName,
      });
      await sea.bundle(outFile);
      // execSync(`chmod +x ${outFile}`);
    }
    return {
      errors: result.errors.map((error) => {
        return new Error(error.detail);
      }),
      artifacts: [
        {
          name: this.artifactName,
          globPatterns: [this.outputDir],
        },
      ],
      metadata: {
        publicDir: this.outputDir,
      },
    };
  }

  static from(options: NodeServerOptions) {
    return new NodeServer(
      options.name,
      options.mainPath,
      options.build,
      options.deploy,
      options.nodeBin,
      options.binary,
      options.artifactName,
      options.bundleFileName,
      options.esbuildOptions,
      options.showNameInOutputs,
      options.distDir,
      options.portRange
    );
  }
}
